import json
import os

import jax
import jax.numpy as jnp
import numpy as np

BASE_DIR = os.path.dirname(os.path.abspath(__file__))


def basic_reduce(inp_path: str) -> np.ndarray:
    x = jnp.load(inp_path)
    return np.asarray(jnp.mean(x, axis=1))


def map_square(inp_path: str) -> np.ndarray:
    x = jnp.load(inp_path)
    return np.asarray(jnp.square(x))


def grad_logistic(inp_path: str) -> np.ndarray:
    data = np.load(inp_path)
    x = jnp.array(data["x"])
    y = jnp.array(data["y"])
    w = jnp.array(data["w"])

    def loss(w_vec):
        logits = jnp.dot(x, w_vec)
        return jnp.mean(jnp.logaddexp(0.0, -y * logits))

    grad = jax.grad(loss)(w)
    return np.asarray(grad)


def scan_rnn(inp_path: str) -> np.ndarray:
    data = np.load(inp_path)
    seq = jnp.array(data["seq"])
    init = jnp.array(data["init"])
    Wx = jnp.array(data["Wx"])
    Wh = jnp.array(data["Wh"])
    b = jnp.array(data["b"])

    def step(h, x_t):
        h_new = jnp.tanh(Wx @ x_t + Wh @ h + b)
        return h_new, h_new

    _, outs = jax.lax.scan(step, init, seq)
    return np.asarray(outs)


def jit_mlp(inp_path: str) -> np.ndarray:
    data = np.load(inp_path)
    X = jnp.array(data["X"])
    W1 = jnp.array(data["W1"])
    b1 = jnp.array(data["b1"])
    W2 = jnp.array(data["W2"])
    b2 = jnp.array(data["b2"])

    def mlp(x):
        h = jnp.maximum(0, x @ W1 + b1)
        return h @ W2 + b2

    out = jax.jit(mlp)(X)
    return np.asarray(out)


TASKS = {
    "basic_reduce": basic_reduce,
    "map_square": map_square,
    "grad_logistic": grad_logistic,
    "scan_rnn": scan_rnn,
    "jit_mlp": jit_mlp,
}


def main() -> None:
    problem_path = os.path.join(BASE_DIR, "problem.json")
    with open(problem_path, "r", encoding="utf-8") as f:
        tasks = json.load(f)

    for task in tasks:
        task_id = task["id"]
        inp_path = os.path.join(BASE_DIR, task["input"])
        out_path = os.path.join(BASE_DIR, task["output"])

        if task_id not in TASKS:
            raise ValueError(f"Unknown task id: {task_id}")

        result = TASKS[task_id](inp_path)
        np.save(out_path, result)


if __name__ == "__main__":
    main()
PY"}
